public ExpectedException thrown = ExpectedException.none();

@Test
public void testRandom_WhenCountIsZero_ReturnsEmptyString() {
    String result = RandomStringUtils.random(0);
    Assert.assertEquals("Should return empty string when count is 0", "", result);
}

@Test
public void testRandom_WhenCountIsNegative_ThrowsIllegalArgumentException() {
    thrown.expect(IllegalArgumentException.class);
    thrown.expectMessage("count must be a positive integer");
    RandomStringUtils.random(-1);
}

@Test
public void testRandom_WhenCountIsOne_ReturnsOneRandomCharacter() {
    String result = RandomStringUtils.random(1);
    Assert.assertThat("Result should be a string of length 1", result, hasLength(1));
    Assert.assertThat("Result should contain only ASCII characters", result, everyItem(isAsciiPrintable()));
}

@Test
public void testRandom_WhenCountIsFive_ReturnsFiveRandomCharacters() {
    String result = RandomStringUtils.random(5);
    Assert.assertThat("Result should be a string of length 5", result, hasLength(5));
    Assert.assertThat("Result should contain only ASCII characters", result, everyItem(isAsciiPrintable()));
}

@Test
public void testRandom_WhenCountIsFiveAndLettersAreAllowed_ReturnsAlphabeticString() {
    String result = RandomStringUtils.random(5, true, false);
    Assert.assertThat("Result should be a string of length 5", result, hasLength(5));
    Assert.assertThat("Result should contain only alphabetic characters", result, everyItem(isAlpha()));
}

@Test
public void testRandom_WhenCountIsFiveAndNumbersAreAllowed_ReturnsNumericString() {
    String result = RandomStringUtils.random(5, false, true);
    Assert.assertThat("Result should be a string of length 5", result, hasLength(5));
    Assert.assertThat("Result should contain only numeric characters", result, everyItem(isNumeric()));
}

