public void testRandom_WhenCountIsFiveAndBothLettersAndNumbersAreAllowed_ReturnsAlphanumericString() {
    String result = RandomStringUtils.random(5, true, true);
    Assert.assertThat("Result should be a string of length 5", result, hasLength(5));
    Assert.assertThat("Result should contain only alphanumeric characters", result, everyItem(isAlphanumeric()));
